1	import { renderClinicians } from './views/clinicians.js';
2	import { renderSlots } from './views/slots.js';
3	import { renderCheckout } from './views/checkout.js';
4	import { renderConfirmation } from './views/confirmation.js';
5	import { startTipsCarousel } from './components/tips-carousel.js';
6	
7	const routes = [
8	  { pattern: /^#\/?$/, view: renderClinicians },
9	  { pattern: /^#\/clinician\/([^/]+)$/, view: renderSlots, params: ['clinicianId'] },
10	  { pattern: /^#\/checkout$/, view: renderCheckout },
11	  { pattern: /^#\/done$/, view: renderConfirmation },
12	];
13	
14	let viewRoot;
15	let cleanup = null;
16	let renderToken = 0;
17	
18	function match(hash) {
19	  for (const route of routes) {
20	    const m = hash.match(route.pattern);
21	    if (m) {
22	      const params = {};
23	      (route.params || []).forEach((name, i) => {
24	        params[name] = decodeURIComponent(m[i + 1]);
25	      });
26	      return { route, params };
27	    }
28	  }
29	  return null;
30	}
31	
32	export function navigate(hash) {
33	  if (location.hash === hash) {
34	    render();
35	  } else {
36	    location.hash = hash;
37	  }
38	}
39	
40	async function render() {
41	  const token = ++renderToken;
42	  if (typeof cleanup === 'function') {
43	    cleanup();
44	  }
45	  cleanup = null;
46	
47	  const hash = location.hash || '#/';
48	  const found = match(hash);
49	  const container = document.createElement('div');
50	  container.className = 'view';
51	  viewRoot.replaceChildren(container);
52	  window.scrollTo(0, 0);
53	
54	  if (!found) {
55	    container.innerHTML = '<h2>Page not found</h2><p><a href="#/">Go to the clinician list</a></p>';
56	    return;
57	  }
58	
59	  const result = await found.route.view(container, { ...found.params, navigate });
60	  if (token === renderToken) {
61	    cleanup = result || null;
62	  } else if (typeof result === 'function') {
63	    result();
64	  }
65	}
66	
67	function markCurrentNav() {
68	  const hash = location.hash || '#/';
69	  for (const link of document.querySelectorAll('.nav-list a')) {
70	    const target = link.getAttribute('href');
71	    if (target === hash || (target === '#/' && hash.startsWith('#/clinician'))) {
72	      link.setAttribute('aria-current', 'page');
73	    } else {
74	      link.removeAttribute('aria-current');
75	    }
76	  }
77	}
78	
79	function start() {
80	  viewRoot = document.getElementById('view');
81	  window.addEventListener('hashchange', () => {
82	    markCurrentNav();
83	    render();
84	  });
85	  markCurrentNav();
86	  render();
87	  startTipsCarousel(document.getElementById('tips-track'));
88	}
89	
90	if (document.readyState === 'loading') {
91	  document.addEventListener('DOMContentLoaded', start);
92	} else {
93	  start();
94	}
