1	const STORAGE_KEY = 'linden.booking.v1';
2	
3	const initial = {
4	  specialty: '',
5	  query: '',
6	  clinician: null,
7	  weekStart: null,
8	  hold: null,
9	  booking: null,
10	};
11	
12	let state = load();
13	const listeners = new Set();
14	
15	function load() {
16	  try {
17	    const raw = sessionStorage.getItem(STORAGE_KEY);
18	    if (!raw) return { ...initial };
19	    const saved = JSON.parse(raw);
20	    if (saved.hold && Date.parse(saved.hold.expiresAt) <= Date.now()) {
21	      saved.hold = null;
22	    }
23	    return { ...initial, ...saved };
24	  } catch {
25	    return { ...initial };
26	  }
27	}
28	
29	function persist() {
30	  try {
31	    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(state));
32	  } catch {
33	    // Storage can be unavailable in private mode; the app still works in memory.
34	  }
35	}
36	
37	export function getState() {
38	  return state;
39	}
40	
41	export function setState(patch) {
42	  state = { ...state, ...patch };
43	  persist();
44	  for (const listener of listeners) {
45	    listener(state);
46	  }
47	}
48	
49	export function subscribe(listener) {
50	  listeners.add(listener);
51	  return () => listeners.delete(listener);
52	}
53	
54	export function resetBooking() {
55	  setState({ clinician: null, weekStart: null, hold: null, booking: null });
