1	const BASE = '/api/v1';
2	const DEFAULT_TIMEOUT_MS = 10000;
3	
4	export class ApiError extends Error {
5	  constructor(message, status, details) {
6	    super(message);
7	    this.name = 'ApiError';
8	    this.status = status;
9	    this.details = details;
10	  }
11	}
12	
13	async function request(path, { method = 'GET', body, timeout = DEFAULT_TIMEOUT_MS } = {}) {
14	  const controller = new AbortController();
15	  const timer = setTimeout(() => controller.abort(), timeout);
16	
17	  let response;
18	  try {
19	    response = await fetch(`${BASE}${path}`, {
20	      method,
21	      headers: body ? { 'Content-Type': 'application/json' } : undefined,
22	      body: body ? JSON.stringify(body) : undefined,
23	      credentials: 'same-origin',
24	      signal: controller.signal,
25	    });
26	  } catch (err) {
27	    if (err.name === 'AbortError') {
28	      throw new ApiError('The request took too long. Please try again.', 0);
29	    }
30	    throw new ApiError('We could not reach the clinic. Check your connection and try again.', 0);
31	  } finally {
32	    clearTimeout(timer);
33	  }
34	
35	  if (response.status === 204) {
36	    return null;
37	  }
38	
39	  let payload = null;
40	  const type = response.headers.get('Content-Type') || '';
41	  if (type.includes('application/json')) {
42	    payload = await response.json();
43	  }
44	
45	  if (!response.ok) {
46	    const message = payload?.error?.message || `Request failed (${response.status}).`;
47	    throw new ApiError(message, response.status, payload?.error?.details);
48	  }
49	  return payload;
50	}
