41	export function startOfWeek(date) {
42	  const d = new Date(date);
43	  const day = d.getDay();
44	  const diff = day === 0 ? -6 : 1 - day;
45	  d.setDate(d.getDate() + diff);
46	  d.setHours(0, 0, 0, 0);
47	  return d;
48	}
