14	function clinicianCard(c) {
15	  const level = availabilityLevel(c);
16	  return `
17	    <li class="clinician">
18	      <h3>${escapeHtml(c.name)}</h3>
19	      <a class="btn btn-secondary" href="#/clinician/${encodeURIComponent(c.id)}">
20	        View times<span class="visually-hidden"> for ${escapeHtml(c.name)}</span>
21	      </a>
22	      <p class="clinician-meta">
23	        <span class="availability availability--${level}"></span>${escapeHtml(c.specialtyName)} · ${escapeHtml(c.location)}
24	      </p>
25	    </li>
26	  `;
27	}
