29	export async function renderClinicians(container) {
30	  const { specialty, query } = getState();
31	
32	  container.innerHTML = `
33	    <section aria-labelledby="find-heading">
34	      <h2 id="find-heading" class="visually-hidden">Find a clinician</h2>
35	      <div class="filters">
36	        <div>
37	          <label class="field-label" for="clinician-search">Search by name</label>
38	          <input id="clinician-search" type="search" tabindex="1" autocomplete="off" value="${escapeHtml(query)}">
39	        </div>
40	        <div id="specialty-slot"></div>
41	      </div>
42	      <p class="legend">
43	        <span class="availability availability--high"></span>Many times this week
44	        <span class="availability availability--low"></span>A few times
45	        <span class="availability availability--none"></span>Fully booked
46	      </p>
47	      <p id="results-count" class="results-count" aria-live="polite"></p>
48	      <ul class="clinician-list" id="clinician-list"></ul>
49	    </section>
50	  `;
51	
52	  const list = container.querySelector('#clinician-list');
53	  const count = container.querySelector('#results-count');
54	  const search = container.querySelector('#clinician-search');
55	
56	  let requestId = 0;
57	  async function refresh() {
58	    const id = ++requestId;
59	    const { specialty: s, query: q } = getState();
60	    try {
61	      const clinicians = await listClinicians({ specialty: s, query: q });
62	      if (id !== requestId) return;
63	      list.innerHTML = clinicians.map(clinicianCard).join('');
64	      count.textContent =
65	        clinicians.length === 1 ? '1 clinician found' : `${clinicians.length} clinicians found`;
66	    } catch (err) {
67	      if (id !== requestId) return;
68	      list.innerHTML = '';
69	      count.textContent = err.message;
70	    }
71	  }
72	
73	  let debounce = 0;
74	  search.addEventListener('input', () => {
75	    window.clearTimeout(debounce);
76	    debounce = window.setTimeout(() => {
77	      setState({ query: search.value.trim() });
78	      refresh();
79	    }, SEARCH_DEBOUNCE_MS);
80	  });
81	
82	  let select = null;
83	  try {
84	    const specialties = await listSpecialties();
85	    select = createSpecialtySelect({
86	      options: specialties,
87	      value: specialty,
88	      onChange(id) {
89	        setState({ specialty: id });
90	        refresh();
91	      },
92	    });
93	    container.querySelector('#specialty-slot').append(select.element);
94	  } catch {
95	    // The filter is optional; the list still loads without it.
96	  }
97	
98	  await refresh();
99	
100	  return () => {
101	    window.clearTimeout(debounce);
102	    select?.destroy();
103	  };
104	}
