15	      <ul class="select-options" hidden>
16	        ${all
17	          .map(
18	            (o) => `
19	          <li class="select-option${o.id === current.id ? ' is-selected' : ''}" data-id="${escapeHtml(o.id)}">
20	            ${escapeHtml(o.name)}
21	          </li>`,
22	          )
23	          .join('')}
24	      </ul>
25	    </div>
26	  `;
27	
28	  const trigger = root.querySelector('.select-trigger');
29	  const list = root.querySelector('.select-options');
30	
31	  function setOpen(next) {
32	    open = next;
33	    list.hidden = !open;
34	  }
35	
36	  function choose(id) {
37	    const next = all.find((o) => o.id === id);
38	    if (!next) return;
39	    current = next;
40	    trigger.textContent = next.name;
41	    for (const item of list.children) {
42	      item.classList.toggle('is-selected', item.dataset.id === id);
43	    }
44	    setOpen(false);
45	    onChange(next.id);
46	  }
