3	export function startTipsCarousel(track) {
4	  if (!track) return () => {};
5	
6	  const slides = Array.from(track.children);
7	  if (slides.length < 2) return () => {};
8	
9	  let index = 0;
10	
11	  function show(next) {
12	    index = (next + slides.length) % slides.length;
13	    track.style.transform = `translateX(-${index * 100}%)`;
14	    slides.forEach((slide, i) => {
15	      slide.setAttribute('aria-hidden', String(i !== index));
16	      for (const link of slide.querySelectorAll('a')) {
17	        link.tabIndex = i === index ? 0 : -1;
18	      }
19	    });
20	  }
21	
22	  show(0);
23	  const timer = window.setInterval(() => show(index + 1), INTERVAL_MS);
24	
25	  return () => window.clearInterval(timer);
26	}
